// (built-in) uniform sampler2D sampler_pw_noise_lq;
vec3 crisp,dx,dy,ret1;
vec2 zz, uv1,uv2;
float  n1,n2,n3,n4,zv,z, noise, k1, wave;
vec2 sunpos;
mat2 ofs;
vec3 suncol;
vec3 cloud (vec2 uv_in) {
return (.2+(1.0+bass_att)*.01/length(uv_in-sunpos)*suncol+(rand_preset.z-.5)*uv_in.y);} 




shader_body
{
vec2 _uv = uv;

sunpos = vec2 (0.0*sin(time/3.0),-.0);
ofs = mat2 (texsize.z,0.0,0.0,texsize.w)*4.0;
suncol = vec3((1.0+normalize(slow_roam_cos.xy)).x);

vec2 uv1 = vec2(_uv.x-0.5+q19,_uv.y-0.5);//*aspect.xy;

dx = texture(sampler_main,_uv+ofs[0]).xyz - texture(sampler_main,_uv-ofs[0]).xyz;
dy = texture(sampler_main,_uv+ofs[1]).xyz - texture(sampler_main,_uv-ofs[1]).xyz;
zz = vec2(dx.b,dy.b);

//clouds
zv = time*.06 ;
zv = (time*.08+ .0*texture(sampler_main, _uv).xyz).x; //##
uv2 = 3.0*uv1+ vec2(0.02*time,-.05*time);

n1 = texture(sampler_noisevol_hq,vec3 (uv2.x,uv2.y,zv)).b;
n2 = texture(sampler_noisevol_hq,vec3 (uv2.x*2.0,uv2.y*2.0,zv*2.0)).b;
n3 = texture(sampler_noisevol_hq,vec3 (uv2.x*4.0,uv2.y*4.0,zv*3.0)).b;
n4 = texture(sampler_noisevol_hq,vec3 (uv2.x*8.0,uv2.y*8.0,zv*7.0)).b;
noise = n1 + n2/2.0 + n3/4.0 + n4/8.0 -1.0;
noise = pow(noise,1.0);
uv2 = uv1+noise*.1;

//*******************************
ret1 = cloud(uv2);
float k1 = .1;
ret = ret1*k1/2.0 + texture(sampler_main, _uv-.02*zz).xyz*(1.0-k1)-.01;

vec4 noise2 = texture(sampler_noisevol_hq, 
                      ((_uv.xyy )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*0.4 
                     ).xyz;
float br = ret.x+ret.y+ret.z;
if(br>.1 && br<=.21)ret += (noise2)*.5; 




}

comp:
shader_body
{



vec2 uva = vec2(uv);
vec2 uvb = vec2(1.0-uv.x,uv.y);

ret = vec3(texture(sampler_main, uva).x + texture(sampler_main, uvb).x);

vec3 blurs = vec3(((texture(sampler_blur1, uva).xyz * scale1) + bias1).x + ((texture(sampler_blur3, uva).xyz * scale3) + bias3).x);
blurs += ((texture(sampler_blur1, uvb).xyz * scale1) + bias1).x + ((texture(sampler_blur3, uvb).xyz * scale3) + bias3).x;


vec2 uv3 = (uv-.5)*(1.0-((texture(sampler_blur1, uv).xy * scale1) + bias1).yy)+.5;
ret += clamp(pow(texture(sampler_main, uv3).zzz,.5)*(1.0-ret.x*2.0), 0.0, 1.0),
ret += clamp(pow(((texture(sampler_blur1, uv3).xyz * scale1) + bias1).zzz,.5)*(1.0-ret.x*2.0), 0.0, 1.0),


ret = mix (
blurs,
ret,
pow(ret,1.0));

ret = pow(ret,vec3(5.0,1.0,.5));

ret += pow(texture(sampler_main, vec2(uv.x,1.0-uv.y)).yyy+texture(sampler_main, 1.0-uv).yyy,vec3(.6,.95,5.0));
vec4 noise9 = texture(sampler_noisevol_hq, 
                      ((uv3.xyy*q28 )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      vec3(1.0,1.0,0.0)*0.05 + 
                      time*vec3(0.0,0.0,1.0)*q31
                     ).xyz;
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 

ret-=slow_roam_sin.xy*roam_cos.zxy*.5;






}
